function useReveal() {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const els = Array.from(ref.current?.querySelectorAll<HTMLElement>(".rev") ?? []);
    const io = new IntersectionObserver(
      (ents) => ents.forEach((e) => e.isIntersecting && e.target.classList.add("in")),
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
    );
    els.forEach((el, i) => { if (el instanceof HTMLElement) el.style.transitionDelay = `${Math.min(i % 4, 3) * 70}ms`; io.observe(el); });
    return () => io.disconnect();
  }, []);
  return ref;
}

